import { ok, fail } from './result.js';
import { isValidDate, daysBetween } from './dates.js';
import { balanceDue } from './payments.js';
import { lineDiscount, lineVat } from './invoices.js';

/**
 * Get overdue invoices.
 * @param {Array<any>} invoices
 * @param {string} asOf - Date in YYYY-MM-DD format
 * @returns {{ ok: true, value: Array<{ number: string, customerId: string, dueDate: string, daysOverdue: number, due: number }> } | { ok: false, error: string }}
 */
export function overdueInvoices(invoices, asOf) {
  if (!isValidDate(asOf)) {
    return fail('DATE_INVALID');
  }

  const overdue = invoices
    .filter(
      (inv) =>
        (inv.status === 'issued' || inv.status === 'partially_paid') &&
        inv.dueDate < asOf
    )
    .map((inv) => ({
      number: inv.number,
      customerId: inv.customerId,
      dueDate: inv.dueDate,
      daysOverdue: daysBetween(inv.dueDate, asOf),
      due: balanceDue(inv),
    }))
    .sort((a, b) => b.daysOverdue - a.daysOverdue);

  return ok(overdue);
}

/**
 * Generate a VAT summary over invoices.
 * @param {Array<any>} invoices
 * @returns {Array<{ rate: number, base: number, vat: number }>}
 */
export function vatSummary(invoices) {
  const rateMap = {};

  for (const invoice of invoices) {
    if (
      invoice.status !== 'issued' &&
      invoice.status !== 'partially_paid' &&
      invoice.status !== 'paid'
    ) {
      continue;
    }

    for (const line of invoice.lines) {
      const rate = line.vatRate ?? 0;
      const discount = lineDiscount(line);
      const lineTotal = line.qty * line.unitPrice;
      const base = lineTotal - discount;
      const vat = lineVat(line);

      if (!rateMap[rate]) {
        rateMap[rate] = { rate, base: 0, vat: 0 };
      }

      rateMap[rate].base += base;
      rateMap[rate].vat += vat;
    }
  }

  return Object.values(rateMap).sort((a, b) => b.rate - a.rate);
}
